macro_rules! deps {
    () => {
        SubobjectExpr!();
        TemplateParam!();
        OperatorName!();
        TemplateArg!();
        UnresolvedName!();
        ExprPrimary!();
        MemberName!();
        FoldExpr!();
        FunctionParam!();
        Initializer!();
    };
}

